    def search_hashtag(
        self,
        *,
        hashtag: str,
        cursor: int | None = None,
        region: str | None = None,
        trim: bool | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> SearchHashtagResponse:
        """Videos under a TikTok hashtag, 30 per page. Items follow Scrape Creators' app layout (`aweme_id`, `statistics`, `video.play_addr`, snake_case `author`), built from TikTok's logged-out web data: a key the web data has no source for is left out, never filled in, and TikTok rounds counts of 10,000 or more for logged-out viewers (1,041,184 plays reads 1,000,000). Pass `cursor` back while `has_more` is 1; TikTok can repeat a video across pages. Costs 1 credit.

        Args:
            hashtag: The hashtag, with or without a leading #.
            cursor: The `cursor` from the previous page. Omit it for the first page.
            region: Two-letter country code for the proxy, such as `US`, `GB` or
                `PH`. TikTok answers as it does to a viewer in that country; it does
                not filter results to that country.
            trim: Set to `true` for the trimmed answer Scrape Creators returns:
                fewer keys per item.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.tiktok.SearchHashtagResponse`.
        """
        return self._send(
            _search_hashtag(hashtag=hashtag, cursor=cursor, region=region, trim=trim),
            timeout=timeout,
        )

